import ast

user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for numpy import
found_numpy = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'numpy' for name in node.names):
        found_numpy = True
    if isinstance(node, ast.ImportFrom) and node.module == 'numpy':
        found_numpy = True

if not found_numpy:
    raise AssertionError('Task 1: Missing import numpy')

# Check for pandas import
found_pandas = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'pandas' for name in node.names):
        found_pandas = True
    if isinstance(node, ast.ImportFrom) and node.module == 'pandas':
        found_pandas = True

if not found_pandas:
    raise AssertionError('Task 1: Missing import pandas')

# Check for dictionary creation (Task 2)
found_dict = False
for node in ast.walk(tree):
    if isinstance(node, ast.Dict):
        found_dict = True

if not found_dict:
    raise AssertionError('Task 2: Missing sales_dict dictionary')

# Check for DataFrame creation (Task 3)
found_df = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'pd' and node.func.attr == 'DataFrame':
            found_df = True

if not found_df:
    raise AssertionError('Task 3: Missing pd.DataFrame() call')

# Check for .head() usage (Task 4)
found_head = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'head':
        found_head = True

if not found_head:
    raise AssertionError('Task 4: Missing .head() call')

# Check for new column creation (Task 5)
found_revenue = False
code_str = user_code.replace(' ', '')
if 'sales_df[\'Revenue\']' in code_str or 'sales_df["Revenue"]' in code_str:
    found_revenue = True

if not found_revenue:
    raise AssertionError('Task 5: Missing Revenue column creation')

# Check for boolean mask using DataFrame column (Task 6)
found_mask = False
if 'sales_df[\'Price\'] > 200' in user_code or 'sales_df["Price"] > 200' in user_code:
    found_mask = True

if not found_mask:
    raise AssertionError('Task 6: Missing boolean mask using sales_df[\'Price\'] > 200')

# Check for applying mask (Task 7)
found_apply_mask = False
if 'sales_df[expensive_mask]' in user_code.replace(' ', ''):
    found_apply_mask = True

if not found_apply_mask:
    raise AssertionError('Task 7: Missing applying mask to DataFrame')

# Check for boolean filtering with & (Task 8)
found_filter = False
if '&' in user_code and 'Units_Sold' in user_code and 'Price' in user_code:
    found_filter = True

if not found_filter:
    raise AssertionError('Task 8: Missing boolean filter with & operator')

# Task 9 validation - flexible: allow either np.mean() or .mean()
found_np_mean = False
found_pd_mean = False
found_np_sum = False
found_pd_sum = False
found_np_max = False
found_pd_max = False

for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == 'np':
                if node.func.attr == 'mean':
                    found_np_mean = True
                if node.func.attr == 'sum':
                    found_np_sum = True
                if node.func.attr == 'max':
                    found_np_max = True
            if node.func.attr == 'mean' and isinstance(node.func.value, ast.Attribute) and 'Revenue' in ast.unparse(node.func.value):
                found_pd_mean = True
            if node.func.attr == 'sum' and isinstance(node.func.value, ast.Attribute) and 'Revenue' in ast.unparse(node.func.value):
                found_pd_sum = True
            if node.func.attr == 'max' and isinstance(node.func.value, ast.Attribute) and 'Revenue' in ast.unparse(node.func.value):
                found_pd_max = True

if not (found_np_mean or found_pd_mean):
    raise AssertionError('Task 9: Missing mean calculation (use either np.mean() or .mean())')
if not (found_np_sum or found_pd_sum):
    raise AssertionError('Task 9: Missing sum calculation (use either np.sum() or .sum())')
if not (found_np_max or found_pd_max):
    raise AssertionError('Task 9: Missing max calculation (use either np.max() or .max())')

# Check for print statements - we expect at least 6 print calls (head + 5 sections)
print_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and 
               isinstance(node.func, ast.Name) and node.func.id == 'print']

if len(print_calls) < 6:
    raise AssertionError('Expected at least 6 print statements (head + 5 report sections)')

print('TEST_PASSED')
